contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint256 cBefore = address(c).balance;
        uint256 ownerBefore = address(this).balance;

        c.sudicideAnyone(); if (__ESBMC_reverted()) return;

        assert(address(c).balance == 0 && address(this).balance >= ownerBefore);
    }

    receive() external payable {}
}

